mapper.select:


    and k.agent_code = #{agentCode}
    and k.action = #{action}
    and k.status = #{status}
    and k.trigger_id = #{triggerId}
    and k.target_type = #{targetType}
    and k.target_id = #{targetId}
    and k.source_event_id = #{sourceEventId}

        and k.create_time >= cast(#{params.beginTime} as date)


        and k.create_time < cast(#{params.endTime} as date) + interval '1 day'


order by k.task_id desc
